          </small>
        </span>
      </NavLink>

      <div className="site-nav-links" aria-label="Main navigation">
        {PAGES.map((page) => (
          <NavLink
            key={page.path}
            to={page.path}
            end={page.path === "/"}
            className={({ isActive }) => (isActive ? "active" : "")}
          >
            {page.label}
          </NavLink>
        ))}
      </div>
    </nav>
  );
