import { useMemo, useState } from "react";
import { Search, SlidersHorizontal, Waves } from "lucide-react";
import fishList from "../reefFishData";

const DIET_FILTERS = [
  "All",
  "Herbivore",
  "Omnivore",
  "Carnivore",
  "Planktivore",
];

export default function Gallery() {
  const [query, setQuery] = useState("");
  const [diet, setDiet] = useState("All");

  const results = useMemo(() => {
    const normalizedQuery = query.toLowerCase().trim();

    return fishList.filter((fish) => {
      const matchesDiet = diet === "All" || fish.diet === diet;
      const searchableText = [
        fish.name,
        fish.scientific,
        fish.family,
        fish.zone,
      ]
        .join(" ")
        .toLowerCase();

      return matchesDiet && searchableText.includes(normalizedQuery);
    });
  }, [diet, query]);

  return (
    <main className="inner-page">
      <header className="page-banner">
        <div>
          <span className="eyebrow">
            <Waves size={15} />
            Species collection
          </span>

          <h1>Fish guide</h1>

          <p>
            Get to know the first ten fish in our growing coral reef field
            guide.
          </p>
        </div>

        <div className="banner-count">
          <strong>{fishList.length}</strong>
          <span>reef species</span>
        </div>
      </header>

      <section className="guide-content">
        <div className="guide-tools">
          <label className="search-box">
            <Search size={18} />
            <input
              type="search"
              placeholder="Search by name or family..."
              aria-label="Search fish by name or family"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
          </label>

          <div className="diet-filter" aria-label="Filter fish by diet">
            <SlidersHorizontal size={17} />

            {DIET_FILTERS.map((item) => (
              <button
                type="button"
                key={item}
                className={diet === item ? "active" : ""}
                onClick={() => setDiet(item)}
              >
                {item}
              </button>
            ))}
          </div>
        </div>

        <p className="result-count">
          Showing {results.length} of {fishList.length} species
        </p>

        <div className="fish-grid">
          {results.map((fish) => (
            <article
              className="fish-card"
              key={fish.id}
              style={{ "--card-color": fish.color }}
            >
              <div className="fish-card-visual">
                <span className="card-index">
                  {String(fishList.indexOf(fish) + 1).padStart(2, "0")}
                </span>

                <div
                  className="detail-fish-illustration card-fish"
                  style={{
                    "--fish-color": fish.color,
                    "--fish-accent": fish.accent,
                  }}
                >
                  <span className="large-tail" />
                  <span className="large-body">
                    <span className="large-stripe" />
                    <span className="large-eye" />
                  </span>
                </div>
              </div>

              <div className="fish-card-content">
                <span className="detail-family">{fish.family}</span>
                <h2>{fish.name}</h2>
                <em>{fish.scientific}</em>
                <p>{fish.description}</p>

                <dl className="fish-card-meta">
                  <div>
                    <dt>Habitat</dt>
                    <dd>{fish.zone}</dd>
                  </div>

                  <div>
                    <dt>Size</dt>
                    <dd>{fish.size}</dd>
                  </div>

                  <div>
                    <dt>Diet</dt>
                    <dd>{fish.diet}</dd>
                  </div>
                </dl>

                <div className="mini-fact">{fish.fact}</div>
              </div>
            </article>
          ))}
        </div>

        {results.length === 0 && (
          <div className="empty-results">
            <Search size={30} />
            <h2>No matching fish</h2>
            <p>Try changing your search or diet filter.</p>
          </div>
        )}
      </section>
    </main>
  );
}

