  font-weight: 800;
}

.card-fish-wrap {
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--fish-color) 13%, #edf9f7);
}

.card-fish-wrap .fish-shape {
  transform: scale(1.5);
}

.card-copy {
  display: flex;
  justify-content: center;
  flex-direction: column;
  padding: 1.3rem;
}

.card-copy small {
  color: var(--fish-color);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.card-copy > strong {
  margin-top: 0.25rem;
  color: #153e4d;
  font-size: 1.12rem;
}

.card-copy em {
  margin-top: 0.2rem;
  color: #84999e;
  font-family: Georgia, serif;
  font-size: 0.76rem;
}

.card-copy > span {
  margin-top: 0.9rem;
  color: #6f8990;
  font-size: 0.7rem;
}

.conservation {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  padding: 4.5rem 8vw;
  color: white;
  background: #063f55;
}

.section-label.light {
  color: #5edbd0;
}

.conservation h2 {
  margin: 0.5rem 0 0;
  font-size: clamp(1.9rem, 3.5vw, 3rem);
  letter-spacing: -0.045em;
}

.conservation p {
  margin: 0;
  align-self: center;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.8;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem 5vw;
  color: #69858d;
  background: #042f40;
}

footer span {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: white;
  font-weight: 800;
}

footer p {
  margin: 0;
  font-size: 0.75rem;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 0.9;
    transform: scale(1);
  }

  50% {
    opacity: 0;
    transform: scale(1.25);
  }
}

@media (max-width: 1000px) {
  .hero-content {
    max-width: 78%;
  }

  .hero-card {
    right: 5%;
  }

  .map-layout {
    grid-template-columns: 1fr;
  }

  .detail-panel {
    padding: 2rem;
  }

  .large-fish-wrap {
    justify-content: start;
  }
}

@media (max-width: 760px) {
  .site-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.8rem;
    padding: 1rem 5vw;
  }

  .site-header nav {
    width: 100%;
    overflow-x: auto;
  }

  .site-header nav a {
    flex: 0 0 auto;
  }

  .hero {
    min-height: 650px;
    align-items: flex-start;
    padding: 4rem 6vw;
  }

  .hero-content {
    max-width: 100%;
  }

  .hero h1 {
    font-size: clamp(2.8rem, 13vw, 4.5rem);
  }

  .hero-card {
    right: 6vw;
    bottom: 2.5rem;
    width: 155px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .search-field {
    width: 100%;
    max-width: none;
  }

  .reef-map {
    min-height: 510px;
  }

  .fish-grid {
    grid-template-columns: 1fr;
  }

  .conservation {
    grid-template-columns: 1fr;
    gap: 1.5rem;
    padding: 3.5rem 6vw;
  }
}

@media (max-width: 520px) {
  .hero {
    min-height: 690px;
  }

  .explorer,
  .collection {
    width: 94%;
    padding-top: 4rem;
  }

  .reef-map {
    min-height: 460px;
  }

  .fish-marker {
    transform: translate(-50%, -50%) scale(0.84);
  }

  .fish-marker:hover,
  .fish-marker.selected {
    transform: translate(-50%, -50%) scale(1);
  }

  .marker-label {
    display: none;
  }

  .detail-panel {
    padding: 1.3rem;
  }

  .fish-stats {
    grid-template-columns: 1fr;
  }

  .fish-card {
    grid-template-columns: 42% 58%;
  }

  footer {
    align-items: flex-start;
    flex-direction: column;
  }
}
